Your expense tracker is below. Add an expense, set a monthly budget, and see totals by category. Entries stay only while this page is open, unless your app lets pages save.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:12px;background:#fafaf7;color:#222}
h2{margin:0 0 8px;font-size:18px}
.card{background:#fff;border:1px solid #e3e3dc;border-radius:10px;padding:12px;margin-bottom:12px}
.row{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px}
input,select,button{font:inherit;padding:6px 8px;border:1px solid #ccc;border-radius:6px}
input{flex:1;min-width:90px}
button{background:#2f7d5b;color:#fff;border:0;cursor:pointer}
button.x{background:#c0392b;padding:2px 8px}
.bar{height:10px;background:#e8efe9;border-radius:5px;overflow:hidden}
.bar>i{display:block;height:100%;background:#2f7d5b}
.over>i{background:#c0392b}
.big{font-size:24px;font-weight:600}
.item{display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid #eee;gap:6px}
.s{color:#777;font-size:12px}
</style></head><body>
<div class="card">
  <h2>This month</h2>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:6px">
    <input id="budget" type="number" placeholder="Monthly budget (₹)">
    <button id="setb">Set</button>
  </div>
  <div class="bar" id="bb"><i id="bf" style="width:0"></i></div>
  <div class="s" id="bt"></div>
</div>
<div class="card">
  <h2>Add expense</h2>
  <div class="row">
    <input id="amt" type="number" placeholder="Amount (₹)">
    <select id="cat"><option>Food</option><option>Rent</option><option>Travel</option><option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option></select>
  </div>
  <div class="row">
    <input id="note" placeholder="Note (optional)">
    <input id="dt" type="date">
    <button id="add">Add</button>
  </div>
</div>
<div class="card"><h2>By category</h2><div id="cats"></div></div>
<div class="card"><h2>Expenses</h2><div id="list"></div></div>
<script>
var items=[],budget=0;
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
var $=function(i){return document.getElementById(i)};
$("dt").value=new Date().toISOString().slice(0,10);
function render(){
  var t=0,c={};
  items.forEach(function(e){t+=e.a;c[e.c]=(c[e.c]||0)+e.a});
  $("total").textContent=fmt(t);
  var bb=$("bb");
  if(budget>0){
    var p=Math.min(100,t/budget*100);
    $("bf").style.width=p+"%";
    bb.className="bar"+(t>budget?" over":"");
    $("bt").textContent=t>budget?"Over budget by "+fmt(t-budget):fmt(budget-t)+" left of "+fmt(budget);
  }else{$("bf").style.width="0";$("bt").textContent="Set a budget to track it.";}
  var h="";
  Object.keys(c).sort(function(x,y){return c[y]-c[x]}).forEach(function(k){
    h+='<div class="item"><span style="width:80px">'+k+'</span><div class="bar" style="flex:1"><i style="width:'+(c[k]/t*100)+'%"></i></div><b>'+fmt(c[k])+'</b></div>';
  });
  $("cats").innerHTML=h||'<div class="s">Nothing yet.</div>';
  var l="";
  items.slice().sort(function(a,b){return b.d.localeCompare(a.d)}).forEach(function(e){
    l+='<div class="item"><div><b>'+fmt(e.a)+'</b> '+e.c+'<div class="s">'+e.d+(e.n?' · '+e.n:'')+'</div></div><button class="x" data-id="'+e.id+'">✕</button></div>';
  });
  $("list").innerHTML=l||'<div class="s">No expenses added.</div>';
}
$("add").onclick=function(){
  var a=parseFloat($("amt").value);
  if(!(a>0))return;
  items.push({id:Date.now()+Math.random(),a:a,c:$("cat").value,n:$("note").value.replace(/[<>&]/g,""),d:$("dt").value});
  $("amt").value="";$("note").value="";render();
};
$("setb").onclick=function(){budget=parseFloat($("budget").value)||0;render()};
$("list").onclick=function(ev){
  var id=ev.target.getAttribute("data-id");
  if(id){items=items.filter(function(e){return String(e.id)!==id});render();}
};
render();
</script></body></html>
```
